mapper.select:
SELECT id, user_id, slot_name, slot_value, polarity, source,
       version, active, created_at, updated_at
FROM city_preference_fact
WHERE user_id = #{userId}
  AND slot_name = #{slotName}
  AND slot_value = #{slotValue}
  AND polarity = #{polarity}
LIMIT 1

mapper.update:
UPDATE city_preference_fact
SET active = 0,
    version = version + 1,
    updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND version = #{expectedVersion}
  AND active = 1
